// New implementation of checkDeclaredPropertyInheritance method
public void checkDeclaredPropertyInheritance(Node node) {
    // Check if the node has any parent
    if (node.getParent() != null) {
        // Get the parent node
        Node parent = node.getParent();

        // Check if the parent node has any children
        if (parent.hasChildren()) {
            // Iterate through the children of the parent node
            for (Node child : parent.children()) {
                // Check if the child node is a STRING_KEY node
                if (child.isStringKey()) {
                    // Get the name of the property from the child node
                    String propertyName = child.getString();

                    // Check if the property name matches the declared property name
                    if (propertyName.equals(node.getString())) {
                        return; // Property is inherited, no need to check further
                    }
                }
            }
        }
    }

    // If the property is not inherited, log a warning
    reportWarning("Property '" + node.getString() + "' is not declared in any parent class.");
}
